def _is_ident_start(ch):
    return ch in _IDENT_START


def _is_ident_char(ch):
    return ch in _IDENT_CHARS


def _apply(op, left, right):
    """Apply an arithmetic operator, translating zero-division to CalcError."""
    try:
        if op == "/":
            return left / right
        if op == "//":
            return left // right
        if op == "%":
