import random, math
random.seed(7)
ops = ["+", "-", "*", "/", "//", "%", "**"]
def gen(depth):
    if depth <= 0 or random.random() < 0.3:
        if random.random() < 0.5:
            return str(random.randint(0, 5))
        return random.choice(["0.5", "1.5", ".5", "2.", "3.0"])
    r = random.random()
    if r < 0.3:
        return "-" + gen(depth-1)
    if r < 0.4:
        return "(" + gen(depth-1) + ")"
    if r < 0.5:
        f = random.choice(["abs", "min", "max"])
        if f == "abs":
            return "abs(" + gen(depth-1) + ")"
        n = random.randint(1, 3)
        return f + "(" + ", ".join(gen(depth-1) for _ in range(n)) + ")"
    return gen(depth-1) + " " + random.choice(ops) + " " + gen(depth-1)

checked = 0
