    except CalcError:
        raise AssertionError(("unexpected CalcError", src))
    if isinstance(want, float):
        ok = isinstance(got, float) and (math.isclose(got, want, rel_tol=1e-12, abs_tol=1e-12) or (math.isnan(got) and math.isnan(want)))
    else:
        ok = got == want and type(got) is type(want)
    assert ok, (src, got, type(got), want, type(want))
    checked += 1
print("differential OK:", checked)
